BLOCK = "\nwith tabs[7]:\n    st.subheader('Cross-checks, noise and limits')\n    ck = pd.DataFrame([\n        ('Sensitivity (Pelgrom-style) vs Monte Carlo', 'f3 sigma 5.62 % predicted vs 5.91 % (x1 mirror); 4.87 vs 4.81 % (x4); Q sigma 3.61 vs 3.68 %'),\n        ('AC vs transient', 'gain within 0.028 dB, phase within 0.14 deg'),\n        ('Tight-tolerance ngspice rerun', 'per-run f3 change at most 0.18 %, Q at most 0.41 %; yield unchanged at 92.7 %'),\n        ('Xyce 7.10, nominal', 'f3 and Q agree to 0.001 %; DC operating point to about 6 digits'),\n        ('Xyce 7.10, injected mismatch', '30 draws of gate offsets: per-run f3 within 0.003 %, Q within 0.014 % (Xyce does not apply the PDK mismatch model)'),\n        ('Seed reproducibility, tt 27 C', '92.3 +/- 1.9 % (750 runs), 92.7 +/- 1.3 % (1500 runs)')], columns=['check', 'result'])\n    st.dataframe(ck, hide_index=True)\n\n    try:\n        st.markdown('#### Xyce vs ngspice, same injected mismatch')\n        fx = P('inj_results.txt')\n        if os.path.exists(fx):\n            R = np.loadtxt(fx)\n            r = R[1:] if len(R) > 2 else R\n            fig = go.Figure()\n            fig.add_trace(go.Scatter(x=r[:, 0], y=r[:, 2], mode='markers', marker=dict(color=BLUE, size=7), name='runs'))\n            lo, hi = float(r[:, 0].min()), float(r[:, 0].max())\n            fig.add_trace(go.Scatter(x=[lo, hi], y=[lo, hi], mode='lines', line=dict(color='white', dash='dot'), name='y = x'))\n            fig.update_xaxes(title_text='ngspice f3 (MHz)')\n            fig.update_yaxes(title_text='Xyce f3 (MHz)')\n            c1, c2 = st.columns([2, 1])\n            c1.plotly_chart(style(fig, 330), width='stretch')\n            d = 100 * (r[:, 2] / r[:, 0] - 1)\n            c2.metric('runs', len(r))\n            c2.metric('max |f3 difference|', '%.3f %%' % abs(d).max())\n            c2.metric('f3 sigma ngspice / Xyce', '%.2f %% / %.2f %%' % (100 * r[:, 0].std() / r[:, 0].mean(), 100 * r[:, 2].std() / r[:, 2].mean()))\n        else:\n            st.info('inj_results.txt not found (run inj.py).')\n    except Exception as e:\n        st.warning('This section could not be drawn: %r' % (e,))\n\n    try:\n        st.markdown('#### Nominal AC response (ngspice, PTAT, tt, 1.8 V, 27 C)')\n        fa = P('curves_ac_nom.txt')\n        if os.path.exists(fa):\n            a = np.loadtxt(fa)\n            ph = a[:, 3]\n            if abs(ph).max() < 7:\n                ph = np.degrees(ph)\n            fig = make_subplots(rows=2, cols=1, shared_xaxes=True, vertical_spacing=0.08)\n            fig.add_trace(go.Scatter(x=a[:, 0] / 1e6, y=a[:, 1], line=dict(color=BLUE), name='magnitude'), row=1, col=1)\n            fig.add_trace(go.Scatter(x=a[:, 0] / 1e6, y=ph, line=dict(color=AMBER), name='phase'), row=2, col=1)\n            fig.add_hline(y=-3, line_dash='dot', line_color='white', row=1, col=1)\n            fig.add_hline(y=-90, line_dash='dot', line_color='white', row=2, col=1)\n            fig.update_xaxes(type='log', title_text='frequency (MHz)', row=2, col=1)\n            fig.update_yaxes(title_text='dB', row=1, col=1)\n            fig.update_yaxes(title_text='degrees', row=2, col=1)\n            st.plotly_chart(style(fig, 420), width='stretch')\n        else:\n            st.info('curves_ac_nom.txt not found (run ac_nom.sh).')\n    except Exception as e:\n        st.warning('This section could not be drawn: %r' % (e,))\n\n    try:\n        st.markdown('#### Summary statistics (Table T-I, PTAT bias)')\n        f1, f2 = P('results_package', 'table_TI_stats.csv'), P('results_package', 'table_TI_extremes.csv')\n        if os.path.exists(f1):\n            st.dataframe(pd.read_csv(f1, index_col=0).round(4))\n        if os.path.exists(f2):\n            st.dataframe(pd.read_csv(f2, index_col=0).round(4))\n        if not (os.path.exists(f1) or os.path.exists(f2)):\n            st.info('results_package/table_TI_*.csv not found (run req_fill.py).')\n    except Exception as e:\n        st.warning('This section could not be drawn: %r' % (e,))\n\n    try:\n        st.markdown('#### Reference exponent: tuned 0.6 vs plain PTAT 1.0 (nominal, 1.8 V)')\n        fs_ = P('alpha_scan.txt')\n        if os.path.exists(fs_):\n            al = pd.read_csv(fs_, sep=r'\\s+')\n            c1, c2 = st.columns(2)\n            fig = go.Figure()\n            for i, (aval, g) in enumerate(al[al.corner == 'tt'].groupby('alpha')):\n                g = g.sort_values('T')\n                fig.add_trace(go.Scatter(x=g['T'], y=g.f3_MHz, mode='lines+markers', name='alpha %.1f' % aval, line=dict(color=[BLUE,GREEN,RED,AMBER,VIOLET][i%5])))\n            fig.add_hline(y=1.6, line_dash='dot', line_color='white')\n            fig.update_xaxes(title_text='temperature (C)')\n            fig.update_yaxes(title_text='f3 (MHz), tt corner')\n            c1.plotly_chart(style(fig, 320), width='stretch')\n            c2.dataframe(al.pivot_table(index=['alpha', 'corner'], columns='T', values='f3_MHz').round(4))\n            st.caption('A true PTAT (alpha 1.0) drifts f3 by about -6 % at -20 C and +6 % at 85 C; a rough estimate puts mean yield near 79 % instead of 88.7 %.')\n        else:\n            st.info('alpha_scan.txt not found (run alpha_scan.sh).')\n    except Exception as e:\n        st.warning('This section could not be drawn: %r' % (e,))\n\n    try:\n        st.markdown('#### Noise (nominal, PTAT)')\n        fn_ = P('curves_noise_pt.txt')\n        if os.path.exists(fn_):\n            nz = np.loadtxt(fn_)\n            f_, on, inn = nz[:, 0], nz[:, 1], nz[:, 3]\n            trap = np.trapezoid if hasattr(np, 'trapezoid') else np.trapz\n            fig = go.Figure()\n            fig.add_trace(go.Scatter(x=f_, y=on * 1e9, line=dict(color=BLUE), name='output'))\n            fig.add_trace(go.Scatter(x=f_, y=inn * 1e9, line=dict(color=AMBER), name='input-referred'))\n            fig.update_xaxes(type='log', title_text='frequency (Hz)')\n            fig.update_yaxes(type='log', title_text='nV/sqrt(Hz)')\n            c1, c2 = st.columns([2, 1])\n            c1.plotly_chart(style(fig, 320), width='stretch')\n            c2.metric('output noise, 1 kHz to 10 MHz', '%.0f uV rms' % (1e6 * np.sqrt(trap(on ** 2, f_))))\n            m = f_ <= 1.6e6\n            o16 = np.sqrt(trap(on[m] ** 2, f_[m]))\n            c2.metric('output noise, up to 1.6 MHz', '%.0f uV rms' % (1e6 * o16))\n            c2.metric('SNR, 100 mV peak sine', '%.1f dB' % (20 * np.log10(0.1 / np.sqrt(2) / o16)))\n        else:\n            st.info('curves_noise_pt.txt not found (run noise_only.sh).')\n    except Exception as e:\n        st.warning('This section could not be drawn: %r' % (e,))\n\n    try:\n        st.markdown('#### Limits')\n        st.markdown('- The PTAT reference is an ideal behavioural source with a tuned exponent, so 88.7 % yield is an upper bound.\\n'\n                    '- Pre-layout only; mismatch coefficients are not validated against silicon.\\n'\n                    '- Xyce cannot apply the PDK mismatch model; PDK statistics are ngspice-only.\\n'\n                    '- SKY130 has weak subthreshold modelling and a large flicker-noise coefficient; noise is not part of the Monte Carlo.')\n    except Exception as e:\n        st.warning('This section could not be drawn: %r' % (e,))\n\n"
import os, shutil, time, sys
fn = 'gmc_app.py'
s = open(fn).read()
if 'Cross-checks and limits' in s:
    print('already patched'); sys.exit(0)
old = "'Bias comparison', 'Study results'])"
if old not in s:
    print('PATTERN NOT FOUND - app not changed'); sys.exit(1)
shutil.copy(fn, 'gmc_app.bak_%s.py' % time.strftime('%Y%m%d_%H%M%S'))
s = s.replace(old, "'Bias comparison', 'Study results', 'Cross-checks and limits'])")
s = s.rstrip('\n') + '\n' + BLOCK
open(fn, 'w').write(s)
print('patched OK')
